using SixLabors.ImageSharp.Formats.Av1.Bitstream;
using SixLabors.ImageSharp.Formats.Av1.Obu;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// End-to-end inter tile decode of a real two-frame 64x64 clip (generated by aomenc with global and
/// warped motion disabled) whose inter frame mixes intra blocks (including filter-intra and non-DC
/// chroma modes) among the inter blocks, and whose chroma carries residual whose transform type must be
/// derived from the chroma mode (intra) or the co-located luma type (inter). Frame 0 (key) is
/// reconstructed by the base decoder and used as the reference; frame 1 is decoded by
/// <see cref="Av1InterTileDecoder"/> and the reconstructed luma and chroma are compared against dav1d's
/// decoded frame.
/// </summary>
public class Av1IntraInInterFrameTests
{
    private static readonly byte[] SequencePayload = Convert.FromHexString("00000002affff034be6010");

    private static readonly byte[] KeyFramePayload = Convert.FromHexString(
        "");

    private static readonly byte[] InterFramePayload = Convert.FromHexString(
        "");

    [Fact]
    public void DecodeIntraInInterFrame_RealClip_MatchesDav1d()
        => DecodeAndCompare(KeyFramePayload, InterFramePayload, Dav1dFrame1LumaBase64, Dav1dFrame1UBase64, Dav1dFrame1VBase64);

    [Fact]
    public void DecodeIntraInInterFrame_NewContentClip_MatchesDav1d()
        => DecodeAndCompare(MixKeyFramePayload, MixInterFramePayload, MixDav1dFrame1LumaBase64, MixDav1dFrame1UBase64, MixDav1dFrame1VBase64);

    private static void DecodeAndCompare(byte[] keyFramePayload, byte[] interFramePayload, string lumaBase64, string uBase64, string vBase64)
    {
        ObuSequenceHeader sequenceHeader = ObuSequenceHeader.Parse(SequencePayload);

        // Frame 0: key frame -> reference.
        Av1BitStreamReader keyReader = new(keyFramePayload);
        ObuFrameHeader keyHeader = ObuFrameHeader.ParseIntra(ref keyReader, sequenceHeader);
        Av1TileDecoder keyDecoder = new(sequenceHeader, keyHeader);
        keyDecoder.DecodeTile(TileData(keyFramePayload, keyHeader));
        Av1ReferenceFrame reference = new(keyHeader.OrderHint, keyDecoder.Luma, keyDecoder.ChromaU, keyDecoder.ChromaV);

        // Frame 1: inter frame mixing intra and inter blocks, with chroma residual.
        int[] referenceOrderHints = new int[8];
        for (int slot = 0; slot < 8; slot++)
        {
            if ((keyHeader.RefreshFrameFlags & (1 << slot)) != 0)
            {
                referenceOrderHints[slot] = keyHeader.OrderHint;
            }
        }

        Av1BitStreamReader interReader = new(interFramePayload);
        ObuFrameHeader interHeader = ObuFrameHeader.ParseInter(ref interReader, sequenceHeader, referenceOrderHints);
        Av1InterTileDecoder interDecoder = new(sequenceHeader, interHeader, reference);
        interDecoder.DecodeTile(TileData(interFramePayload, interHeader));

        Assert.Equal(64, interDecoder.Luma.Width);
        Assert.Equal(64, interDecoder.Luma.Height);

        AssertPlaneMatches(interDecoder.Luma.Samples, lumaBase64, "luma");
        AssertPlaneMatches(interDecoder.ChromaU.Samples, uBase64, "chroma U");
        AssertPlaneMatches(interDecoder.ChromaV.Samples, vBase64, "chroma V");
    }

    private static void AssertPlaneMatches(ReadOnlySpan<ushort> actual, string expectedBase64, string planeName)
    {
        byte[] expected = Convert.FromBase64String(expectedBase64);
        int exact = 0;
        int maxDiff = 0;
        for (int i = 0; i < expected.Length; i++)
        {
            int diff = Math.Abs(actual[i] - expected[i]);
            maxDiff = Math.Max(maxDiff, diff);
            Assert.True(diff <= 2, $"{planeName} sample {i}: got {actual[i]}, dav1d {expected[i]}.");
            if (actual[i] == expected[i])
            {
                exact++;
            }
        }

        Assert.True(exact >= expected.Length * 90 / 100, $"Only {exact}/{expected.Length} {planeName} samples matched exactly (maxDiff {maxDiff}).");
    }

    private static ReadOnlyMemory<byte> TileData(byte[] framePayload, ObuFrameHeader header)
    {
        int tileGroupStart = (header.EndBitPosition + 7) >> 3;
        ObuTileGroup tileGroup = ObuTileGroup.Parse(framePayload.AsSpan(tileGroupStart), header);
        (int offset, int length) = tileGroup.GetTile(0);
        return framePayload.AsMemory(tileGroupStart + offset, length);
    }

    private static readonly byte[] MixKeyFramePayload = Convert.FromHexString(
        "");

    private static readonly byte[] MixInterFramePayload = Convert.FromHexString(
        "");

    private const string Dav1dFrame1LumaBase64 =
        "";

    private const string Dav1dFrame1UBase64 =
        "";

    private const string Dav1dFrame1VBase64 =
        "";

    private const string MixDav1dFrame1LumaBase64 =
        "";

    private const string MixDav1dFrame1UBase64 =
        "";

    private const string MixDav1dFrame1VBase64 =
        "";
}
